import pandas as pd


def _seg_differs(seg_s, seg_c):
    """NULL vs NULL -> not different; NULL vs non-NULL -> different;
    otherwise compare values."""
    s_na = pd.isna(seg_s)
    c_na = pd.isna(seg_c)
    if s_na and c_na:
        return False
    if s_na != c_na:
        return True
    return seg_s != seg_c


def run(inputs: dict) -> dict:
    dim = inputs['DIM_CUSTOMER'].copy()
    stg = inputs['STG_CUSTOMER'].copy()
    fact = inputs['FACT_TXN'].copy()

    # normalize date-like columns for safe comparisons
    for col in ('eff_start_date', 'eff_end_date'):
        if col in dim.columns:
            dim[col] = pd.to_datetime(dim[col], errors='coerce')
    if 'update_date' in stg.columns:
        stg['update_date'] = pd.to_datetime(stg['update_date'], errors='coerce')
    if 'txn_date' in fact.columns:
        fact['txn_date'] = pd.to_datetime(fact['txn_date'], errors='coerce')

    # max surrogate key before the load
    if dim.empty or dim['customer_sk'].isna().all():
        max_sk = 0
    else:
        max_sk = int(dim['customer_sk'].max())

    # current row per customer_id (at most one expected)
    current = dim[dim['is_current'] == 1].set_index('customer_id', drop=False)

    create_flags = []
    for _, row in stg.iterrows():
        cid = row['customer_id']
        if cid not in current.index:
            create_flags.append(True)
        else:
            cur_seg = current.loc[cid, 'segment']
            create_flags.append(_seg_differs(row['segment'], cur_seg))

    stg = stg.reset_index(drop=True)
    stg['_create'] = create_flags

    creating = stg[stg['_create']].copy()
    creating = creating.sort_values('customer_id', kind='mergesort').reset_index(drop=True)
    creating['customer_sk'] = [max_sk + i + 1 for i in range(len(creating))]

    # expire current rows for customers that get a new version
    dim_updated = dim.copy()
    expire_ids = set(creating['customer_id'].tolist())

    for cid in expire_ids:
        if cid in current.index:
            idx = dim_updated[
                (dim_updated['customer_id'] == cid) & (dim_updated['is_current'] == 1)
            ].index
            upd_date = creating.loc[creating['customer_id'] == cid, 'update_date'].iloc[0]
            dim_updated.loc[idx, 'eff_end_date'] = upd_date
            dim_updated.loc[idx, 'is_current'] = 0

    if len(creating) > 0:
        new_rows = pd.DataFrame({
            'customer_sk': creating['customer_sk'].values,
            'customer_id': creating['customer_id'].values,
            'segment': creating['segment'].values,
            'eff_start_date': creating['update_date'].values,
            'eff_end_date': pd.NaT,
            'is_current': 1,
        })
    else:
        new_rows = pd.DataFrame(columns=[
            'customer_sk', 'customer_id', 'segment',
            'eff_start_date', 'eff_end_date', 'is_current'
        ])

    dim_customer_out = pd.concat([dim_updated, new_rows], ignore_index=True)

    # enforce dtypes where reasonable
    if 'customer_sk' in dim_customer_out.columns:
        dim_customer_out['customer_sk'] = dim_customer_out['customer_sk'].astype('int64')
    if 'customer_id' in dim_customer_out.columns:
        dim_customer_out['customer_id'] = dim_customer_out['customer_id'].astype('int64')
    if 'is_current' in dim_customer_out.columns:
        dim_customer_out['is_current'] = dim_customer_out['is_current'].astype('int64')

    # Step 2: key facts against the updated dimension
    dim_by_cust = {}
    for cid, grp in dim_customer_out.groupby('customer_id'):
        dim_by_cust[cid] = grp[['customer_sk', 'eff_start_date', 'eff_end_date']].to_dict('records')

    def find_sk(row):
        cid = row['customer_id']
        txn_date = row['txn_date']
        versions = dim_by_cust.get(cid, [])
        for v in versions:
            start = v['eff_start_date']
            end = v['eff_end_date']
            if pd.isna(start):
                continue
            if start <= txn_date and (pd.isna(end) or txn_date < end):
                return v['customer_sk']
        return -1

    if len(fact) > 0:
        fact['customer_sk'] = fact.apply(find_sk, axis=1)
    else:
        fact['customer_sk'] = pd.Series(dtype='int64')

    fact['customer_sk'] = fact['customer_sk'].astype('int64')

    fact_txn_keyed = fact[['txn_id', 'customer_sk', 'amount']].copy()

    return {
        'dim_customer_out': dim_customer_out,
        'fact_txn_keyed': fact_txn_keyed,
    }
